"use server";

import { omit } from "lodash";
import { revalidateTag } from "next/cache";
import { redirect } from "next/navigation";
import { sdk } from "@/lib/config";
import medusaError from "@/lib/utils/medusa-error";
import { getAuthHeaders, getCartId, removeCartId, setCartId } from "./cookies";
import { getProductsById } from "./products";
import { getRegion } from "./regions";
export async function retrieveCart() {
  const cartId = await getCartId();
  if (!cartId) {
    return null;
  }
  return await sdk.store.cart.retrieve(cartId, {}, {
    next: {
      tags: ["cart"]
    },
    ...(await getAuthHeaders())
  }).then(({
    cart
  }) => cart).catch(() => {
    return null;
  });
}
export async function getOrSetCart(countryCode) {
  let cart = await retrieveCart();
  const region = await getRegion(countryCode);
  if (!region) {
    throw new Error(`Region not found for country code: ${countryCode}`);
  }
  if (!cart) {
    const cartResp = await sdk.store.cart.create({
      region_id: region.id
    });
    cart = cartResp.cart;
    setCartId(cart.id);
    revalidateTag("cart");
  }
  if (cart && cart?.region_id !== region.id) {
    await sdk.store.cart.update(cart.id, {
      region_id: region.id
    }, {}, await getAuthHeaders());
    revalidateTag("cart");
  }
  return cart;
}
export async function updateCart(data) {
  const cartId = await getCartId();
  if (!cartId) {
    throw new Error("No existing cart found, please create one before updating");
  }
  return sdk.store.cart.update(cartId, data, {}, await getAuthHeaders()).then(({
    cart
  }) => {
    revalidateTag("cart");
    return cart;
  }).catch(medusaError);
}
export async function addToCart({
  variantId,
  quantity,
  countryCode
}) {
  if (!variantId) {
    throw new Error("Missing variant ID when adding to cart");
  }
  const cart = await getOrSetCart(countryCode);
  if (!cart) {
    throw new Error("Error retrieving or creating cart");
  }
  await sdk.store.cart.createLineItem(cart.id, {
    variant_id: variantId,
    quantity
  }, {}, await getAuthHeaders()).then(() => {
    revalidateTag("cart");
  }).catch(medusaError);
}
export async function updateLineItem({
  lineId,
  quantity
}) {
  if (!lineId) {
    throw new Error("Missing lineItem ID when updating line item");
  }
  const cartId = await getCartId();
  if (!cartId) {
    throw new Error("Missing cart ID when updating line item");
  }
  await sdk.store.cart.updateLineItem(cartId, lineId, {
    quantity
  }, {}, await getAuthHeaders()).then(() => {
    revalidateTag("cart");
  }).catch(medusaError);
}
export async function deleteLineItem(lineId) {
  if (!lineId) {
    throw new Error("Missing lineItem ID when deleting line item");
  }
  const cartId = await getCartId();
  if (!cartId) {
    throw new Error("Missing cart ID when deleting line item");
  }
  await sdk.store.cart.deleteLineItem(cartId, lineId, await getAuthHeaders()).then(() => {
    revalidateTag("cart");
  }).catch(medusaError);
  revalidateTag("cart");
}
export async function enrichLineItems(lineItems, regionId) {
  if (!lineItems) return [];

  // Prepare query parameters
  const queryParams = {
    ids: lineItems.map(lineItem => lineItem.product_id),
    regionId: regionId
  };

  // Fetch products by their IDs
  const products = await getProductsById(queryParams);
  // If there are no line items or products, return an empty array
  if (!lineItems?.length || !products) {
    return [];
  }

  // Enrich line items with product and variant information
  const enrichedItems = lineItems.map(item => {
    const product = products.find(p => p.id === item.product_id);
    const variant = product?.variants?.find(v => v.id === item.variant_id);

    // If product or variant is not found, return the original item
    if (!product || !variant) {
      return item;
    }

    // If product and variant are found, enrich the item
    return {
      ...item,
      variant: {
        ...variant,
        product: omit(product, "variants")
      }
    };
  });
  return enrichedItems;
}
export async function setShippingMethod({
  cartId,
  shippingMethodId
}) {
  return sdk.store.cart.addShippingMethod(cartId, {
    option_id: shippingMethodId
  }, {}, await getAuthHeaders()).then(() => {
    revalidateTag("cart");
  }).catch(medusaError);
}
export async function initiatePaymentSession(cart, data) {
  return sdk.store.payment.initiatePaymentSession(cart, data, {}, await getAuthHeaders()).then(resp => {
    revalidateTag("cart");
    return resp;
  }).catch(medusaError);
}
export async function applyPromotions(codes) {
  const cartId = await getCartId();
  if (!cartId) {
    throw new Error("No existing cart found");
  }
  await updateCart({
    promo_codes: codes
  }).then(() => {
    revalidateTag("cart");
  }).catch(medusaError);
}
